/* Pixel-style calculator with cohesive palette */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --highlight: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.calculator {
  background: var(--card);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 0 var(--highlight), 0 12px 24px rgba(0,0,0,0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--highlight);
  margin-bottom: 8px;
}

label {
  font-size: 1rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
}

input, select, button {
  font-family: inherit;
  font-size: 1.2rem;
  padding: 12px;
  border: 3px solid var(--highlight);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus, button:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

button {
  background: var(--accent);
  color: var(--text);
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: none;
  box-shadow: 0 4px 0 var(--highlight);
  transition: transform 0.1s, box-shadow 0.1s;
}

button:hover {
  background: #ff5e7e;
}

button:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 var(--highlight);
}

#result {
  display: block;
  background: var(--bg);
  border: 3px solid var(--highlight);
  border-radius: 8px;
  padding: 16px;
  font-size: 2rem;
  font-weight: bold;
  text-align: right;
  min-height: 4rem;
  word-break: break-all;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--highlight);
  margin-top: 8px;
}

.inputs {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Responsive */
@media (max-width: 400px) {
  .calculator {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  input, select, button {
    font-size: 1rem;
    padding: 10px;
  }
}

[hidden] {
  display: none !important;
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateBtn = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function calculate() {
  const leftStr = leftInput.value.trim();
  const rightStr = rightInput.value.trim();
  const operation = operationSelect.value;

  // Reject empty inputs
  if (leftStr === '' || rightStr === '') {
    resultOutput.textContent = 'Error';
    return;
  }

  const left = Number(leftStr);
  const right = Number(rightStr);

  // Reject non-finite numbers
  if (!isFinite(left) || !isFinite(right)) {
    resultOutput.textContent = 'Error';
    return;
  }

  let result;
  switch (operation) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        resultOutput.textContent = 'Error';
        return;
      }
      result = left / right;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  // Check if result is finite (e.g., overflow)
  if (!isFinite(result)) {
    resultOutput.textContent = 'Error';
    return;
  }

  resultOutput.textContent = result;
}

calculateBtn.addEventListener('click', calculate);

// Allow Enter key in inputs to trigger calculation
[leftInput, rightInput].forEach(input => {
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      calculate();
    }
  });
});
